local function get_popup_typename(type)
    local type_name = 'unknown'
    if type == POPUP_TYPE.TYPE_REALNAME then
        type_name = 'realname'
    elseif type == POPUP_TYPE.TYPE_ANTI_ADDICTION then
        type_name = 'anti_addiction'
    elseif type == POPUP_TYPE.TYPE_OPERATION then
        type_name = 'operation'
    end

    return type_name
end

local function get_close_event_data(type)
    return "close_event_data_" .. get_popup_typename(type)
end

local function get_current_ptoken()
    local eg = require 'ejoysdk_lua.ejoysdk_gangplank'
    local current_vendor_name = eg.get_last_login()
    E.LOG.debug(TAG, 'get_current_ptoken, current vendor:' .. (current_vendor_name or 'nil'))

    local vendor = EV.get(current_vendor_name)
    local ptoken = nil
    if vendor and vendor.get_auth_info then
        --E.LOG.debug(TAG, 'get_current_ptoken, current vendor has get_auth_info method, try get authinfo')
        local auth_info = vendor.get_auth_info()
        ptoken = auth_info and auth_info.ptoken
        E.LOG.debug(TAG, 'get_current_ptoken, current vendor has get_auth_info method, ptoken:' .. (ptoken or 'nil'))
    end
    E.LOG.debug(TAG, 'get_current_ptoken result ptoken:' .. (ptoken or 'nil'))
    return ptoken
end

local function realname_status_report(cb)
    local function realname_report_callback(succ, ...)
        if succ then
            local data = ...
            if cb then
                cb(true, data.realNameInfo)
            end
        else
            local code, msg = ...
            E.LOG.warn(TAG, 'realname_report_callback failed, code:' .. tostring(code) .. ', msg:' .. tostring(msg))
            if cb then
                cb(false, code, msg)
            end
        end
    end

    local ptoken = get_current_ptoken()

    --notify server query realname status
    local report_params = {
        --token = 'fwx120191212chau5df21181ffb53f296424b7ec0000000'
        token = ptoken
    }

    -- for test env
    --LP.set_env(LP.ENV.DEBUG)
    LP.post(LP.SERVICE.REALNAME_INFO_REPORT, report_params, realname_report_callback)
end

local function is_current_vendor_lingxi()
    local v_aligames = require "ejoysdk_lua.vendors.aligames"
    local is_for_lingxi = v_aligames.is_for_lingxi()
    if is_for_lingxi then
        E.LOG.debug(TAG, 'is_current_vendor_lingxi: current IS for lingxi vendor')
    else
