local function get_ali_ios_authinfo(auth_info)
    --auth_info = "auth_type=\"PURE_OAUTH_SDK\"&app_id=\"2017010604890084\"&scope=\"auth_user\"&state=\"1578922929917\""
    --             auth_type=\"PURE_OAUTH_SDK\"&app_id=\"2017010604890084\"&scope=\"auth_user\"&state=\"1578989194137\"
    local auth_type
    auth_info:gsub('auth_type="(.-)"', function(value)
        auth_type = value or 'PURE_OAUTH_SDK'
    end)
    local app_id
    auth_info:gsub('app_id="(.-)"', function(value)
        app_id = value
    end)
    local scope
    auth_info:gsub('scope="(.-)"', function(value)
        scope = value or 'auth_user'
    end)
    local state
    auth_info:gsub('state="(.-)"', function(value)
        state = value or 'auth_state'
    end)
    return 'https://authweb.ali' .. 'p' .. 'a' .. 'y.com/auth?auth_type=' .. tostring(auth_type) .. '&app_id=' .. tostring(app_id) ..
            '&scope=' .. tostring(scope) .. '&state=' .. tostring(state)
end

-- 1. webview close
