local function listen_webview_event(popup_type, can_close, need_check_anti_addiction, realname_callback)
    E.LOG.debug(TAG, 'need_check_anti_addiction=' .. tostring(need_check_anti_addiction))
    local close_event_data = get_close_event_data(popup_type)

    local result_handled = false

    -- 默认页面关闭处理（非成功）
    local function default_close_callback(_status)
        if popup_type == POPUP_TYPE.TYPE_OVERSEAS_REALNAME then
            -- 海外实名有只成功与取消
            realname_callback(UC_REALNAME_STATUS.STATUS_REALNAME_CLOSED_BY_USER)

            -- 实名制结果
            QL.commit_action_main("ejoy_realname_result", popup_type, false)
        else
            if can_close then
                E.LOG.warn(TAG, 'default_close_callback, the popup can close, so notify gangplank to continue')
                realname_callback(REALNAME_INFO.REALNAME_RESULT.STATUS_COMPLETE_WITH_REALNAME_FAILED)

                -- 实名制结果
                QL.commit_action_main("ejoy_realname_result", REALNAME_INFO.REALNAME_RESULT.STATUS_COMPLETE_WITH_REALNAME_FAILED, true)
            else
                E.LOG.warn(TAG, 'default_close_callback, the popup can not close, so notify gangplank to logout')
                realname_callback(REALNAME_INFO.REALNAME_RESULT.STATUS_UNCOMPLETE)

                -- 实名制结果
                QL.commit_action_main("ejoy_realname_result", _status, false)
            end
        end

    end

    -- 是否检查防沉迷
    --local function check_anti_addiction_handler(anti_addiction_status)
    --    if anti_addiction_status == LX_ANTI_ADDICTION_STATUS.NORMAL then
    --        -- 实名成功，且无需防沉迷。此前是沉迷状态，所以需要刷新状态
    --        if popup_type == POPUP_TYPE.TYPE_ANTI_ADDICTION then
    --            E.LOG.debug(TAG, 'realname success, and not in anti-addiction state, popup type is anti-addiction, so notify gangplank reget state')
    --            realname_callback(REALNAME_INFO.REALNAME_RESULT.STATUS_COMPLETE_WITH_STATE_CHANGED)
    --        else
    --            E.LOG.debug(TAG, 'realname success, and not in anti-addiction state, popup type is realname, so notify gangplank to continue')
    --            realname_callback(REALNAME_INFO.REALNAME_RESULT.STATUS_PROCESS_COMPLETE)
    --        end
    --    elseif anti_addiction_status == LX_ANTI_ADDICTION_STATUS.IN_ANTI_ADDICTION then
    --        -- 实名成功，且需要防沉迷：重新acquire gangplank
    --        E.LOG.debug(TAG, 'realname success, and in anti-addiction state, need notify gangplank to reget state')
    --        realname_callback(M..STATUS_COMPLETE_WITH_STATE_CHANGED)
    --    end
    --end

    -- 实名制填写结果通知灵犀服务器结果
    local function report_callback(succ, ...)
        if succ then
            -- {"antiAddictionStatus":1,"personId":"","realNameStatus":0,"adult":0},"popupConfigList":[]}
            local realname_info = ...
            -- 更新实名制状态
            REALNAME_INFO.set_realname_info(realname_info)
            if realname_info.realNameStatus == REALNAME_INFO.LX_REALNAME_STATUS.SUCCESS then
                --if need_check_anti_addiction then
                --    E.LOG(TAG, 'need_check_anti_addiction is true, now start check!')
                --    check_anti_addiction_handler(realname_info.antiAddictionStatus)
                --else
                --    -- 实名制成功，且无需检查防沉迷，所以返回成功
                --    E.LOG.debug(TAG, 'realname failed, the popup can close, so notify gangplank to continue')
                --    realname_callback(REALNAME_INFO.REALNAME_RESULT.STATUS_PROCESS_COMPLETE)
                --end

                -- 实名制成功，且无需检查防沉迷，所以返回成功
                E.LOG.debug(TAG, 'realname failed, the popup can close, so notify gangplank to continue')
                realname_callback(REALNAME_INFO.REALNAME_RESULT.STATUS_COMPLETE_WITH_REALNAME_SUCC)

                -- 实名制结果
                QL.commit_action_main("ejoy_realname_result", nil, true)
            else
                --其它异常
                default_close_callback(CC.GANGPLANK_ERROR_CODE.GANGPLANK_ERROR_REALNAME_REPORT_RESULT_INVALID)
            end
        else
            local code, msg = ...
            E.LOG.warn(TAG, 'realname_report_callback failed, code:' .. tostring(code) .. ', msg:' .. tostring(msg))
            --其它异常
            default_close_callback(code, msg)
        end
    end

    --js 事件监听
    local function webview_js_callback(_value)
        E.LOG.debug(TAG, 'webview_js_callback received>>')
        local args = _value.args or {}
        E.LOG.debug(TAG, args)

        local aliAuth = 'ali' .. 'p' .. 'a' .. 'y' .. 'Auth'

        local stat_params = {
            msg = args.type
        }
        if args.type == 'msg_realname' then
            local status = (args.params and args.params.status) or -1
            local status_str = tostring(status)
            E.LOG.debug(TAG, "#webview_js_callback receive realname callback, status:" .. tostring(status))
            -- process realname status here
            if status_str == UC_REALNAME_STATUS.STATUS_SUCCESS then
                result_handled = true
                if popup_type == POPUP_TYPE.TYPE_OVERSEAS_REALNAME then
                    realname_callback(UC_REALNAME_STATUS.STATUS_SUCCESS)
                    return
                end

                REALNAME_INFO.update_realname_status(REALNAME_INFO.LX_REALNAME_STATUS.SUCCESS)

                -- 实名制打点：回调成功
                if can_close then
                    ESTAT.stat_bizid(REALNAME_STAT_BIZID.REALNAME_STAT_NOT_FORCE_RESULT, '4', '1', { is_priority_high = true })
                else
                    ESTAT.stat_bizid(REALNAME_STAT_BIZID.REALNAME_STAT_FORCE_RESULT, '4', '1', { is_priority_high = true })
                end
                --上报服务端判断,没有配置的情况下，默认上报
                local report = (args.params or {}).report
                if report == nil or report then
                    E.LOG.debug(TAG, 'webview_js_callback realname callback success! now report to lx server')
                    realname_status_report(report_callback)
                else
                    --前端实名后，根据结果判断是否需要再次acquire或退出登录
                    E.LOG.debug(TAG, "webview_js_callback realname and report callback success! now handle report callback")
                    local realname_info = (args.params or {}).realNameInfo
                    E.LOG.debug(TAG, "realname_info >>>")
                    E.LOG.debug(TAG, realname_info)
                    report_callback(true, realname_info)
                end
            elseif status_str == UC_REALNAME_STATUS.STATUS_LOGIN_STATUS_INVALID then
                result_handled = true

                E.LOG.warn(TAG, 'webview_js_callback realname callback login status invalid!')

                QL.commit_action_main("ej_realname_status_login_invalid", popup_type, can_close, stat_params)
                realname_callback(REALNAME_INFO.REALNAME_RESULT.STATUS_UNCOMPLETE)
            elseif status_str == UC_REALNAME_STATUS.STATUS_REALNAME_CLOSED_BY_USER then
                result_handled = true

                E.LOG.warn(TAG, 'webview_js_callback realname callback dialog closed by user!')
                --check if can close, and if not then logout else notify login success

                -- 实名制打点：关闭非强制实名制
                if can_close and popup_type ~= POPUP_TYPE.TYPE_OVERSEAS_REALNAME then
                    ESTAT.stat_bizid(REALNAME_STAT_BIZID.REALNAME_STAT_NOT_FORCE_CLOSE, '3', '1', { is_priority_high = true })
                end

                QL.commit_action_main("ej_realname_status_close_by_user", popup_type, can_close, stat_params)

                default_close_callback(status)
            else
                -- 实名制打点：回调失败
                if popup_type ~= POPUP_TYPE.TYPE_OVERSEAS_REALNAME then
                    if can_close then
                        ESTAT.stat_bizid(REALNAME_STAT_BIZID.REALNAME_STAT_NOT_FORCE_RESULT, '4', '0', { is_priority_high = true })
                    else
                        ESTAT.stat_bizid(REALNAME_STAT_BIZID.REALNAME_STAT_FORCE_RESULT, '4', '0', { is_priority_high = true })
                    end
                end

                QL.commit_action_main("ej_realname_status_other_result", popup_type, can_close, stat_params)
            end
        elseif args.type == 'msg_login_intercept' then
            result_handled = true
            -- 登录拦截的回调，状态码复用之前实名制的
            local status = (args.params and args.params.status) or -1
            local status_str = tostring(status)
            E.LOG.debug(TAG, "#webview_js_callback receive msg_login_intercept callback, status:" .. tostring(status))
            if status_str == UC_REALNAME_STATUS.STATUS_SUCCESS then
                realname_callback(UC_REALNAME_STATUS.STATUS_SUCCESS)
            else
                realname_callback(status_str)
            end

            stat_params.code = status_str
            QL.commit_action_main("ej_realname_status_intercept", popup_type, can_close, stat_params)
        elseif args.type == 'msg_exit_login' then
            -- 用户点击退出按钮
            result_handled = true
            E.LOG.debug(TAG, "#webview_js_callback receive msg_exit_login, and notify user relogin")

            -- 实名制打点：关闭非强制实名制
            if popup_type == POPUP_TYPE.TYPE_REALNAME and can_close then
                ESTAT.stat_bizid(REALNAME_STAT_BIZID.REALNAME_STAT_NOT_FORCE_CLOSE, '3', '1', { is_priority_high = true })
            end

            -- open bind phone page
            realname_callback(REALNAME_INFO.REALNAME_RESULT.STATUS_UNCOMPLETE)
            -- stat
            QL.commit_action_main("ej_realname_status_exit_login", popup_type, can_close, stat_params)
            -- 对灵犀绑定手机的兼容处理：灵犀封装的绑定手机页面，绑定成功后的js回调的type是logout
        elseif popup_type ~= POPUP_TYPE.TYPE_REALNAME and args.type == 'logout' or args.type == 'bind_succ' then
            result_handled = true

            E.LOG.debug(TAG, "#webview_js_callback receive bind phone callback, and notify user relogin")
            local v_aligames = require "ejoysdk_lua.vendors.aligames"
            v_aligames.set_lx_guest_bind_state();

            -- open bind phone page
            realname_callback(REALNAME_INFO.REALNAME_RESULT.STATUS_COMPLETE_BIND_PHONE)

            -- stat
            QL.commit_action_main("ej_realname_status_bind_relogin", popup_type, can_close, stat_params)
        elseif args.type == aliAuth then
            E.LOG.debug(TAG, '#webview_js_callback receive aliAuth')

            local v_aligames = require "ejoysdk_lua.vendors.aligames"
            local auth_info = args.authInfo or ''
            if E.Sysinfo.os() == 'ios' then
                auth_info = get_ali_ios_authinfo(auth_info)
            end
            v_aligames.ali_auth(auth_info, function(succ, ...)
                if succ then
                    local cbid = _value.cbid
                    E.LOG.debug(TAG, 'cbid: ' .. tostring(cbid))
                    local auth_result = ...
                    if cbid then
                        E.WebView.callback_js(cbid, auth_result)
                    end

                    -- stat
                    stat_params.code = auth_result
                    QL.commit_action_main("ej_realname_status_ali_auth_ret", popup_type, can_close, stat_params)
                end
            end)
        end
    end

    -- webview 关闭事件监听
    local function webview_close_callback(_value)
        E.LOG.debug(TAG, "#listen_webview_close_event, receive close event")

        if _value and _value.args == close_event_data then
            E.LOG.debug(TAG, "#listen_webview_close_event, event>>" .. tostring(_value.args))

            -- check if can close
            if not result_handled then
                E.LOG.debug(TAG, "#listen_webview_close_event, receive close event，it's user close")

                -- 实名制打点：关闭非强制实名制
                if popup_type == POPUP_TYPE.TYPE_REALNAME and can_close then
                    ESTAT.stat_bizid(REALNAME_STAT_BIZID.REALNAME_STAT_NOT_FORCE_CLOSE, '3', '1', { is_priority_high = true })
                end

                QL.commit_action_main("ej_realname_web_close", popup_type, can_close)

                default_close_callback(CC.GANGPLANK_ERROR_CODE.GANGPLANK_ERROR_REALNAME_CANCELLED)
            end

            ET.unsubscribe('webview_close', webview_close_callback)
            ET.unsubscribe('webview_jsargs', webview_js_callback)
        end
    end

    ET.subscribe('webview_close', webview_close_callback)
    ET.subscribe('webview_jsargs', webview_js_callback)
end

local function show_webview(popup_type, url, start_up_data, can_close, need_check_anti_addiction, screen_orientation, realname_callback)
    E.LOG.debug(TAG, 'show_webview popup type:' .. tostring(popup_type) .. ', type_name:' .. tostring(get_popup_typename(popup_type)) .. ', url:' .. tostring(url))
    local local_startup_data = start_up_data

    -- 0为fragment， 1为activity
    local launch_mode = E.CONFIG.get_config("realname_launch_mode")

    local white_host_list = {
        '.ejoy.com', '30.103.73.187', '.uc.cn', '.aligames.com', '.9game.cn', '.alibaba-inc.com', '.hepinggames.com', '.lingxigames.com', '.qookkagames.com', '.sialiagames.com.tw', '.suixiagames.com'
    }
    local host = {}
    for _, hostname in ipairs(white_host_list) do
        host[hostname] = {
            transparent = true,
            startupData = local_startup_data
        }
    end

    local new_white_hosts = CONFIG.get_white_hosts()
    for _, new_host in pairs(new_white_hosts) do
        host[new_host] = { transparent = true, startupData = local_startup_data }
    end

    E.WebView.open(url, host, {
        compactMode = true,
        use_cutout = true,
        screen_orientation = screen_orientation,
        closeEventData = get_close_event_data(popup_type),
        use_fragment = (launch_mode and { launch_mode == 0 } or { true })[1]
    })

    -- 实名制打点：触发实名制
    if type == POPUP_TYPE.TYPE_REALNAME or type == POPUP_TYPE.TYPE_ANTI_ADDICTION then
        if can_close then
            ESTAT.stat_bizid(REALNAME_STAT_BIZID.REALNAME_STAT_NOT_FORCE, '2', '1', { is_priority_high = true})
        else
            ESTAT.stat_bizid(REALNAME_STAT_BIZID.REALNAME_STAT_FORCE, '2', '1', { is_priority_high = true })
        end
    end

    --监听 webview 事件
    listen_webview_event(popup_type, can_close, need_check_anti_addiction, realname_callback)
end

local function get_cas_client_info()
    local cas_client_info_str = ''
    local pkg_info = E.get_pkg_info()
    cas_client_info_str = cas_client_info_str .. 'machine:' .. pkg_info.model .. '`'
    cas_client_info_str = cas_client_info_str .. 'app_name:' .. E.Sysinfo.app_name() .. '`'
    cas_client_info_str = cas_client_info_str .. 'os:' .. E.Sysinfo.os() .. '`'
    cas_client_info_str = cas_client_info_str .. 'game_id:' .. pkg_info.game_id .. '`'
    cas_client_info_str = cas_client_info_str .. 'utdid:' .. pkg_info.utdid .. '`'

    if E.Sysinfo.os() == 'android' then
        cas_client_info_str = cas_client_info_str .. 'imei:' .. pkg_info.imei .. '`'
        cas_client_info_str = cas_client_info_str .. 'client_identity:' .. 'lxandroid' .. '`'
    elseif E.Sysinfo.os() == 'ios' then
        cas_client_info_str = cas_client_info_str .. 'idfa:' .. E.Sysinfo.idfa() .. '`'
        cas_client_info_str = cas_client_info_str .. 'client_identity:' .. 'lxios' .. '`'

    elseif E.Sysinfo.os() == 'windows' then
        cas_client_info_str = cas_client_info_str .. 'idfa:' .. E.Sysinfo.idfa() .. '`'
        cas_client_info_str = cas_client_info_str .. 'client_identity:' .. 'lxwindows' .. '`'
    end

    return cas_client_info_str
end

--[[判断str是否以substr结尾。是返回true，否返回false，失败返回失败信息]]
local endswith = function(str, substr)
    if str == nil or substr == nil then
        return nil, "the string or the sub-string parameter is nil"
    end
    local str_tmp = string.reverse(str)
    local substr_tmp = string.reverse(substr)
    if string.find(str_tmp, substr_tmp) ~= 1 then
        return false
    else
        return true
    end
end

local function get_url_parts(url)
    local parts = {}
    local query_index = string.find(url, '?', 1, true)
    local fragment_index = string.find(url, '#', 1, true)
    parts.url_base = url
    parts.url_query = nil
    parts.url_fragment = nil
    if query_index and query_index > 1 then
        if fragment_index and fragment_index > 1 then
            parts.url_base = string.sub(url, 1, math.min(query_index, fragment_index) - 1)
            if fragment_index > query_index then
                parts.url_fragment = string.sub(url, fragment_index)
                parts.url_query = string.sub(url, query_index, fragment_index - 1)
            else
                parts.url_fragment = string.sub(url, fragment_index, query_index - 1)
                parts.url_query = string.sub(url, query_index)
            end
        else
            parts.url_base = string.sub(url, 1, query_index - 1)
            parts.url_query = string.sub(url, query_index)
        end
    end

    if endswith(parts.url_base, "/") then
        local url_len = string.len(parts.url_base)
        parts.url_base = string.sub(parts.url_base, 1, url_len - 1)
    end

    return parts
end

local function get_query_parameter(url, key)
    local parts = get_url_parts(url)

    local url_query_params = {}
    if parts.url_query then
        -- skip ? character
        local query_str = string.sub(parts.url_query, 2)
        url_query_params = E.HTTP.parse_query(query_str)
    end

    return url_query_params[key]
end

local function append_query_params(url, params)
    if not params then
        E.LOG.debug(TAG, 'appendUrlPath params is nil')
        return url
    end

    local parts = get_url_parts(url)

    local url_query_params = {}
    if parts.url_query then
        -- skip ? character
        local query_str = string.sub(parts.url_query, 2)
        url_query_params = E.HTTP.parse_query(query_str)
    end

    -- 覆盖url自带的参数信息
    for k, v in pairs(params) do
        local origin_val = url_query_params[k]
        if origin_val ~= v then
            E.LOG.debug(TAG, 'append_query_params, overide url param, k:' .. tostring(k) .. ', override v:' .. tostring(v) .. ', origin v:' .. tostring(origin_val))
            url_query_params[k] = v
        end
    end

    local append_query_params_str = ''
    for k, v in pairs(url_query_params) do
        append_query_params_str = append_query_params_str .. E.HTTP.escape(tostring(k)) .. '=' .. E.HTTP.escape(tostring(v))
        append_query_params_str = append_query_params_str .. '&'
    end

    -- 去除query_params_str字符串末尾的&符号
    local query_params_str_len = string.len(append_query_params_str)
    append_query_params_str = string.sub(append_query_params_str, 1, query_params_str_len - 1)
    parts.url_query = '?' .. append_query_params_str

    local result = parts.url_base .. parts.url_query
    if parts.url_fragment then
        result = result .. parts.url_fragment
    end

    return result
end

local function append_sdk_query_params(url, need_cas, params)
    ----例子： 'http://30.103.88.22:1234/s3/request_cas/index.html?sdk_type=2&st=st776620ef82x9t3iv8pgk6v8y0c1ghd&client_info=imei:`imsi:`mac:44%3A66%3AFC%3A5E%3ABE%3AE3`machine:PACT00`app_name:GameSdk`os:android`game_id:100000`client_identity:ALIGAME`'
    local combinded_params = params or {}

    -- 2：表示lua sdk 打开H5页面
    combinded_params.sdk_type = 2

    combinded_params.ver = '2.0' --  1.0 : 不支持自定义界面的UI版本 2.0 : 支持自定义界面的UI版本

    local is_support_ali_auth = false
    if is_current_vendor_lingxi() then
        E.LOG.debug(TAG, 'append_sdk_query_params current is lingxi channel, now check if support ali auth')
        local v_aligames = require "ejoysdk_lua.vendors.aligames"
        is_support_ali_auth = v_aligames.is_support_ali_auth()
    end

    local is_support_key = 'is_support_al' .. 'ip' .. 'ay_auth'
    combinded_params[is_support_key] = is_support_ali_auth
    if is_support_ali_auth then
        E.LOG.debug(TAG, 'append_sdk_query_params is_support_ali_auth: true')
    else
        E.LOG.debug(TAG, 'append_sdk_query_params is_support_ali_auth: false')
    end

    local os = E.Sysinfo.os()
    if os == 'android' then
        combinded_params.client_id = LP.APPID.FOR_LX_ANROID
    elseif os == 'ios' then
        combinded_params.client_id = LP.APPID.FOR_LX_IOS
    end

    if need_cas then
        local sdk_type = 'ali' .. 'p' .. 'a' .. 'y' .. 'sdk_type'
        local is_installed = 'is_' .. 'ali' .. 'p' .. 'a' .. 'y' .. '_installed'
        if os == 'android' then
            combinded_params[sdk_type] = 'full' -- 完整版SDK
            combinded_params[is_installed] = E.Sysinfo.is_app_install(ANDROID_ALI_PKG_NAME)
        elseif os == 'ios' then
            combinded_params[sdk_type] = 'pure' -- 极简版SDK
            local ali_bundle_name = 'ali' .. 'p' .. 'a' .. 'y:'
            combinded_params[is_installed] = E.Sysinfo.is_app_install(ali_bundle_name)
        end

        -- 获取支付宝实名制控制显示和隐藏的总开关
        local disable_ali_key = 'ej_disable_ali' .. 'p' .. 'a' .. 'y_auth'
        local disable_ali_auth = get_query_parameter(url, disable_ali_key)
        if not disable_ali_auth or disable_ali_auth == 'false' then
            E.LOG.debug(TAG, 'NOT has ej_disable_ali_auth or is false, so check ali available')
            local v_aligames = require "ejoysdk_lua.vendors.aligames"
            combinded_params.is_support_ali_auth = v_aligames.is_support_ali_auth()
            if combinded_params.is_support_ali_auth and combinded_params[is_installed] then
                combinded_params.realname_type = 'ali' .. 'p' .. 'a' .. 'y' .. '_auth'
            else
                combinded_params.realname_type = 'id_number'
            end
        else
            E.LOG.debug(TAG, 'has ej_disable_ali_auth, so hide realname type')
            combinded_params.realname_type = 'id_number'
        end

        combinded_params.client_info = get_cas_client_info()
    end

    local realname_ex = REALNAME_INFO.get_realname_ex()
    if realname_ex and next(realname_ex) ~= nil then
        for k, v in pairs(realname_ex) do
            combinded_params[k] = v
        end
    end

    -- 这里暂时写死方便调试，正常是H5从cookie读取
    --combinded_params.st = 'st778620e01ppfsbme712x8d489vnt36'
    return append_query_params(url, combinded_params)
end

