-- 处理 tips 消息
local function handle_notify_tips(config, cb)
    if config.notifyMsg and config.notifyMsg ~= '' then
        if cb then
            cb(true)
        end
    else
        E.LOG.warn(TAG, 'msg is invalid, empty or nil')
        if cb then
            cb(false, -1, 'config.notifyMsg is invalid, empty or nil')
        end
    end
end

local function show_with_popup_info(popup_info, cb)
    -- get type from attach_info
    local popup_type = popup_info.type
    -- get can close flag from url, 2 代表不可关闭
    local can_close = popup_info.pageClose ~= 2
    E.LOG.debug(TAG, 'handle_login_reject_error, need show popup type:' .. tostring(popup_type) .. ', type_name:' .. tostring(get_popup_typename(popup_type)) .. ', pageClose:' .. tostring(popup_info.pageClose))

    local url = append_sdk_query_params(popup_info.configUrl, true)
    E.LOG.debug(TAG, 'handle_login_reject_error append_cas_query result:' .. tostring(url))
    local start_up_data = {}
    CONFIG.fill_start_up_data(start_up_data)
    start_up_data.client_info = get_cas_client_info()

    show_webview(popup_type, url, start_up_data, can_close, true, nil, cb)
end

-- 处理弹窗消息
local function handle_notify_h5(config, cb)
    local popup_list = config.popupConfigList
    if popup_list == nil or next(popup_list) == nil then
        E.LOG.debug(TAG, 'popup list is empty, no need to show h5')
        if cb then
            cb(false, -1, 'config.popupConfigList is empty, no need to show h5')
        end
        return
    end

    local popup_info = popup_list[1]
    show_with_popup_info(popup_info, function(result_status)
        if result_status == REALNAME_INFO.REALNAME_RESULT.STATUS_COMPLETE_WITH_REALNAME_FAILED
                or result_status == REALNAME_INFO.REALNAME_RESULT.STATUS_COMPLETE_WITH_REALNAME_SUCC then
            E.LOG.debug(TAG, 'popup complete, receive popup handle result STATUS_COMPLETE_WITH_STATE_CHANGED STATUS_PROCESS_COMPLETE')
        else
            E.LOG.debug(TAG, 'receive popup handle result not complete, need logout!')
            local eg = require 'ejoysdk_lua.ejoysdk_gangplank'
            eg.logout()
        end
        if cb then
            cb(true)
        end
    end)
end

-- 消息推送弹窗展示，协议结构参考这里：https://yuque.antfin-inc.com/mxb7qq/confluence-sdkdev-vg6uys/tenvg0
-- true: 已完成消费该消息，false: 未完成消费该消息
function M.show_popup_with_config(config, cb)
    if not config then
        E.LOG.warn(TAG, 'show_popup_with_config failed, config is nil')
        if cb then
            cb(false, -1, 'config is nil')
        end
    end

    E.LOG.debug(TAG, 'receive notify message with type:' .. tostring(config.type))
    if config.type == NOTIFY_TYPE.WEB then
        handle_notify_h5(config, cb)
    elseif config.type == NOTIFY_TYPE.TIPS then
        handle_notify_tips(config, cb)
    else
        E.LOG.warn(TAG, 'not support popup config:' .. (config.type or 'nil'))
        if cb then
            cb(false, -1, 'config.type must be "tips" or "h5"')
        end
    end
end

-- 处理实名制检查
function M.handle_realname_pages(page_type, scene, can_close, cb)
    assert(type(page_type) == 'string', 'page_type should not recognized:'..(page_type or 'nil'))
    local url = REALNAME_PAGES[page_type]
    assert(type(url) == 'string', 'url not found with page_type:'..page_type)
    --游客绑定页面
    local params = {
        scene_type = scene
    }

    local need_cas = false
    if page_type == M.REALNAME_PAGE_TYPE.REALNAME_URL then
        need_cas = true
    end
    -- FIXME 这里可以直接使用M.open_page的,但append_sdk_query_params逻辑甚多还是分开处理
    local modify_url = append_sdk_query_params(url, need_cas, params)
    show_webview(POPUP_TYPE.TYPE_DEFAULT, modify_url, {}, can_close, false, nil, cb)
end

function M.handle_overseas_realname_page(url, scene, can_close, params, cb)
    M.open_page(POPUP_TYPE.TYPE_OVERSEAS_REALNAME, url, scene, can_close, params, cb)
end

function M.open_page(type, url, scene, can_close, params, cb)
    params = params or {}
    params.scene_type = scene

    -- 数据不再需要拼接到query里，直接放到startup_data里
    --local modify_url = append_query_params(url, params)
    show_webview(type, url, params, can_close, false, nil, cb)
end

function M.handle_login_reject_error(status, ejoy_token, attach_info, cb)
    E.LOG.debug(TAG, 'handle_login_reject_error, status:' .. tostring(status) .. ' ejoy_token:' .. tostring(ejoy_token))

    if attach_info then
        --get si from acquire result attach_info
        LP.set_si(attach_info.guestId)
    end

    -- 如果attach_info为空，则不处理
    if attach_info == nil or next(attach_info) == nil or next(attach_info.popupConfigList) == nil then
        E.LOG.debug(TAG, 'attach_info or popup list is empty, no need realname or anti addiction')
        E.LOG.debug(TAG, attach_info or 'nil')

        return false
    end

    if status ~= M.ERR_CODE_NEED_REALNAME_OR_ANTI_ADDICTION and status ~= 200 then
        E.LOG.debug(TAG, 'status no recognized, no need realname or anti addiction')
        return false
    end

    E.LOG.debug(TAG, 'handle_login_reject_error popup handler handled this status')


    -- 服务端每次只会下发一个弹窗
    local popup_info = attach_info.popupConfigList[1]
    show_with_popup_info(popup_info, cb)

    return true
end

